    "settings.heading": "\u0627\u0644\u062A\u0632\u0627\u0645\u0646",
    "settings.language": "\u0644\u063A\u0629",
    "settings.languageDescription": "\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u0629 \u0645\u0646 \u0642\u0628\u0644 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062C \u0627\u0644\u0645\u0633\u0627\u0639\u062F. \u064A\u062A\u0628\u0639 \u0627\u0644\u0646\u0638\u0627\u0645 Obsidian \u0648\u0646\u0638\u0627\u0645 \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u062E\u0627\u0635 \u0628\u0643.",
    "settings.rootFolder": "\u0627\u0644\u0645\u062C\u0644\u062F \u0627\u0644\u062C\u0630\u0631 \u0644\u0645\u0644\u0627\u062D\u0638\u0629 \u0627\u0644\u0645\u0647\u0645\u0629",
    "settings.rootFolderDescription": "\u064A\u062A\u0645 \u0625\u0646\u0634\u0627\u0621 \u0645\u0644\u0627\u062D\u0638\u0629 Markdown \u0645\u062A\u062F\u0627\u062E\u0644\u0629 \u0648\u0627\u062D\u062F\u0629 \u0644\u0643\u0644 \u0645\u0647\u0645\u0629.",
    "settings.dashboardNote": "\u0645\u0644\u0627\u062D\u0638\u0629 \u0644\u0648\u062D\u0629 \u0627\u0644\u0642\u064A\u0627\u062F\u0629",
    "settings.interval": "\u0627\u0644\u0641\u0627\u0635\u0644 \u0627\u0644\u0632\u0645\u0646\u064A \u0644\u0644\u0645\u0632\u0627\u0645\u0646\u0629 \u0627\u0644\u062A\u0644\u0642\u0627\u0626\u064A\u0629",
    "settings.intervalDescription": "\u062F\u0642\u0627\u0626\u0642 \u0628\u064A\u0646\u0645\u0627 \u064A\u0643\u0648\u0646 Obsidian \u0645\u0641\u062A\u0648\u062D\u064B\u0627. \u064A\u0633\u0631\u064A \u0645\u0641\u0639\u0648\u0644\u0647 \u0628\u0639\u062F \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u062A\u062D\u0645\u064A\u0644.",
    "settings.token": "Todoist API \u0627\u0644\u0645\u0645\u064A\u0632",
    "settings.tokenDescription": "\u0645\u062E\u0632\u0646\u0629 \u0628\u0634\u0643\u0644 \u0622\u0645\u0646 \u0641\u064A Obsidian SecretStorage. \u0623\u062F\u062E\u0644 \u0631\u0645\u0632\u064B\u0627 \u0645\u0645\u064A\u0632\u064B\u0627 \u062C\u062F\u064A\u062F\u064B\u0627 \u0644\u062D\u0641\u0638\u0647 \u0623\u0648 \u0627\u0633\u062A\u0628\u062F\u0627\u0644\u0647\u061B \u0644\u0627 \u064A\u062A\u0645 \u0639\u0631\u0636 \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0645\u062D\u0641\u0648\u0638\u0629 \u0623\u0628\u062F\u064B\u0627.",
    "settings.tokenPlaceholderEmpty": "\u0627\u0644\u0635\u0642 \u0631\u0645\u0632 Todoist API \u0627\u0644\u062E\u0627\u0635 \u0628\u0643",
    "settings.tokenPlaceholderSaved": "\u064A\u062A\u0645 \u062A\u062E\u0632\u064A\u0646 \u0627\u0644\u0631\u0645\u0632 \u0628\u0634\u0643\u0644 \u0622\u0645\u0646",
    "settings.tokenStatusChecking": "\u062C\u0627\u0631\u064D \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u0627\u0644\u062A\u062E\u0632\u064A\u0646 \u0627\u0644\u0622\u0645\u0646\u2026",
    "settings.tokenStatusManaged": "\u064A\u062A\u0645 \u062D\u0641\u0638 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u0645\u064A\u0632 \u0644\u0647\u0630\u0627 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062C \u0627\u0644\u0645\u0633\u0627\u0639\u062F.",
