    "settings.secretKeyDescription": "\u064A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u0645\u064A\u0632 \u0627\u0644\u0630\u064A \u062A\u0645 \u062A\u0643\u0648\u064A\u0646\u0647 \u0628\u0627\u0644\u0641\u0639\u0644 \u0628\u0648\u0627\u0633\u0637\u0629 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062C \u0627\u0644\u0625\u0636\u0627\u0641\u064A \u0644\u0644\u0645\u0632\u0627\u0645\u0646\u0629 \u0627\u0644\u062D\u0627\u0644\u064A. \u0644\u0627 \u064A\u062A\u0645 \u062D\u0641\u0638 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u0645\u064A\u0632 \u0646\u0641\u0633\u0647 \u0647\u0646\u0627 \u0623\u0628\u062F\u064B\u0627.",
