    "settings.interval": "\u0410\u045E\u0442\u0430\u043C\u0430\u0442\u044B\u0447\u043D\u044B \u0456\u043D\u0442\u044D\u0440\u0432\u0430\u043B \u0441\u0456\u043D\u0445\u0440\u0430\u043D\u0456\u0437\u0430\u0446\u044B\u0456",
