    "settings.tokenPlaceholderEmpty": "\u041F\u043E\u0441\u0442\u0430\u0432\u0435\u0442\u0435 \u0432\u0430\u0448\u0438\u044F Todoist API \u0442\u043E\u043A\u0435\u043D",
    "settings.tokenPlaceholderSaved": "\u0422\u043E\u043A\u0435\u043D\u044A\u0442 \u0441\u0435 \u0441\u044A\u0445\u0440\u0430\u043D\u044F\u0432\u0430 \u0441\u0438\u0433\u0443\u0440\u043D\u043E",
