    "settings.tokenPlaceholderEmpty": "\u0631\u0645\u0632 Todoist API \u062E\u0648\u062F \u0631\u0627 \u062C\u0627\u06CC\u06AF\u0630\u0627\u0631\u06CC \u06A9\u0646\u06CC\u062F",
    "settings.tokenPlaceholderSaved": "\u06CC\u06A9 \u0646\u0634\u0627\u0646\u0647 \u0628\u0647 \u0637\u0648\u0631 \u0627\u06CC\u0645\u0646 \u0630\u062E\u06CC\u0631\u0647 \u0645\u06CC \u0634\u0648\u062F",
    "settings.tokenStatusChecking": "\u062F\u0631 \u062D\u0627\u0644 \u0628\u0631\u0631\u0633\u06CC \u0641\u0636\u0627\u06CC \u0630\u062E\u06CC\u0631\u0647\u200C\u0633\u0627\u0632\u06CC \u0627\u06CC\u0645\u0646\u2026",
    "settings.tokenStatusManaged": "\u06CC\u06A9 \u062A\u0648\u06A9\u0646 \u0628\u0631\u0627\u06CC \u0627\u06CC\u0646 \u0627\u0641\u0632\u0648\u0646\u0647 \u0630\u062E\u06CC\u0631\u0647 \u0634\u062F\u0647 \u0627\u0633\u062A.",
