    "settings.intervalDescription": "\u10E0\u10D0\u10DB\u10D3\u10D4\u10DC\u10D8\u10DB\u10D4 \u10EC\u10E3\u10D7\u10D8, \u10E1\u10D0\u10DC\u10D0\u10DB \u10DD\u10D1\u10E1\u10D8\u10D3\u10D8\u10D0\u10DC\u10D8 \u10E6\u10D8\u10D0\u10D0. \u10EB\u10D0\u10DA\u10D0\u10E8\u10D8 \u10E8\u10D4\u10D3\u10D8\u10E1 \u10D2\u10D0\u10D3\uFFFD\uFFFD\u10E2\u10D5\u10D8\u10E0\u10D7\u10D5\u10D8\u10E1 \u10E8\u10D4\u10DB\u10D3\u10D4\u10D2.",
    "settings.token": "Todoist API \u10DF\u10D4\u10E2\u10DD\u10DC\u10D8",
    "settings.tokenDescription": "\u10E3\u10E1\u10D0\u10E4\u10E0\u10D7\u10EE\u10DD\u10D3 \u10D8\u10DC\u10D0\u10EE\u10D4\u10D1\u10D0 Obsidian SecretStorage-\u10E8\u10D8. \u10E8\u10D4\u10D8\u10E7\u10D5\u10D0\u10DC\u10D4\u10D7 \u10D0\u10EE\u10D0\u10DA\u10D8 \u10DF\u10D4\u10E2\u10DD\u10DC\u10D8 \u10DB\u10D8\u10E1 \u10E8\u10D4\u10E1\u10D0\u10DC\u10D0\u10EE\u10D0\u10D3 \u10D0\u10DC \u10E8\u10D4\u10E1\u10D0\u10EA\u10D5\u10DA\u10D4\u10DA\u10D0\u10D3; \u10E8\u10D4\u10DC\u10D0\u10EE\u10E3\u10DA\u10D8 \u10DB\u10DC\u10D8\u10E8\u10D5\u10DC\u10D4\u10DA\u10DD\u10D1\u10D0 \u10D0\u10E0\u10D0\u10E1\u10DD\u10D3\u10D4\u10E1 \u10D0\u10E0\u10D8\u10E1 \u10DC\u10D0\u10E9\u10D5\u10D4\u10DC\u10D4\u10D1\u10D8.",
    "settings.tokenPlaceholderEmpty": "\u10E9\u10D0\u10E1\u10D5\u10D8\u10D7 \u10D7\u10E5\u10D5\u10D4\u10DC\u10D8 Todoist API \u10DF\u10D4\u10E2\u10DD\u10DC\u10D8",
    "settings.tokenPlaceholderSaved": "\u10DF\u10D4\u10E2\u10DD\u10DC\u10D8 \u10E3\u10E1\u10D0\u10E4\u10E0\u10D7\u10EE\u10DD\u10D3 \u10D8\u10DC\u10D0\u10EE\u10D4\u10D1\u10D0",
    "settings.tokenStatusChecking": "\u10DB\u10D8\u10DB\u10D3\u10D8\u10DC\u10D0\u10E0\u10D4\u10DD\u10D1\u10E1 \u10E3\u10E1\u10D0\u10E4\u10E0\u10D7\u10EE\u10DD \u10DB\u10D4\u10EE\u10E1\u10D8\u10D4\u10E0\u10D4\u10D1\u10D8\u10E1 \u10E8\u10D4\u10DB\u10DD\u10EC\u10DB\u10D4\u10D1\u10D0\u2026",
    "settings.tokenStatusManaged": "\u10DF\u10D4\u10E2\u10DD\u10DC\u10D8 \u10E8\u10D4\u10DC\u10D0\u10EE\u10E3\u10DA\u10D8\u10D0 \u10D0\u10DB \u10DB\u10DD\u10D3\u10E3\u10DA\u10D8\u10E1\u10D7\u10D5\u10D8\u10E1.",
    "settings.tokenStatusShared": "Todoist Sync-\u10D8\u10E1 \u10DB\u10D8\u10D4\u10E0 \u10E3\u10D9\u10D5\u10D4 \u10E8\u10D4\u10DC\u10D0\u10EE\u10E3\u10DA\u10D8 \u10DF\u10D4\u10E2\u10DD\u10DC\u10D8\u10E1 \u10D2\u10D0\u10DB\u10DD\u10E7\u10D4\u10DC\u10D4\u10D1\u10D0.",
    "settings.tokenStatusMissing": "\u10DF\u10D4\u10E2\u10DD\u10DC\u10D8 \u10D0\u10DB\u10DF\u10D0\u10DB\u10D0\u10D3 \u10D0\u10E0 \u10D0\u10E0\u10D8\u10E1 \u10EE\u10D4\u10DA\u10DB\u10D8\u10E1\u10D0\u10EC\u10D5\u10D3\u10DD\u10DB\u10D8.",
    "settings.saveToken": "\u10DF\u10D4\u10E2\u10DD\u10DC\u10D8\u10E1 \u10E8\u10D4\u10DC\u10D0\u10EE\u10D5\u10D0",
    "settings.replaceToken": "\u10DF\u10D4\u10E2\u10DD\u10DC\u10D8\u10E1 \u10E8\u10D4\u10EA\u10D5\u10DA\u10D0",
    "settings.removeToken": "\u10DF\u10D4\u10E2\u10DD\u10DC\u10D8\u10E1 \u10EC\u10D0\u10E8\u10DA\u10D0",
    "settings.removeTokenTitle": "\u10EC\u10D0\u10D8\u10E8\u10D0\u10DA\u10DD\u10E1 \u10E8\u10D4\u10DC\u10D0\u10EE\u10E3\u10DA\u10D8 Todoist \u10DF\u10D4\u10E2\u10DD\u10DC\u10D8?",
    "settings.removeTokenDescription": "\u10D4\u10E1 \u10E8\u10DA\u10D8\u10E1 \u10DB\u10EE\u10DD\u10DA\u10DD\u10D3 Todoist Task Notes-\u10D8\u10E1 \u10DB\u10D8\u10D4\u10E0 \uFFFD\uFFFD\u10D4\u10DC\u10D0\u10EE\u10E3\u10DA \u10DF\u10D4\u10E2\u10DD\u10DC\u10E1. Todoist Sync-\u10D8\u10E1 \u10DB\u10D8\u10D4\u10E0 \u10E8\u10D4\u10DC\u10D0\u10EE\u10E3\u10DA\u10D8 \u10DF\u10D4\u10E2\u10DD\u10DC\u10D8 \u10D0\u10E0 \u10D8\u10EA\u10D5\u10DA\u10D4\u10D1\u10D0.",
    "settings.secretKey": "\u10E1\u10D0\u10D4\u10E0\u10D7\u10DD \u10E1\u10D0\u10D8\u10D3\u10E3\u10DB\u10DA\u10DD \u10D2\u10D0\u10E1\u10D0\u10E6\u10D4\u10D1\u10D8",
    "settings.secretKeyDescription": "\u10D8\u10E7\u10D4\u10DC\u10D4\u10D1\u10E1 \u10DF\u10D4\u10E2\u10DD\u10DC\u10E1, \u10E0\u10DD\u10DB\u10D4\u10DA\u10D8\u10EA \u10E3\u10D9\u10D5\u10D4 \u10D9\u10DD\u10DC\u10E4\u10D8\u10D2\u10E3\u10E0\u10D8\u10E0\u10D4\u10D1\u10E3\u10DA\u10D8\u10D0 \u10D0\u10E0\u10E1\u10D4\u10D1\u10E3\u10DA\u10D8 \u10E1\u10D8\u10DC\u10E5\u10E0\u10DD\u10DC\u10D8\u10D6\u10D0\u10EA\u10D8\u10D8\u10E1 \u10DB\u10DD\u10D3\u10E3\u10DA\u10D8\u10D7. \u10D7\u10D0\u10D5\u10D0\u10D3 \u10DF\u10D4\u10E2\u10DD\u10DC\u10D8 \u10D0\u10E5 \u10D0\u10E0\u10D0\u10E1\u10DD\u10D3\u10D4\u10E1 \u10D0\u10E0\u10D8\u10E1 \u10E8\u10D4\u10DC\u10D0\u10EE\u10E3\u10DA\u10D8.",
    "settings.connection": "API \u10D9\u10D0\u10D5\u10E8\u10D8\u10E0\u10D8",
    "settings.connectionDescription": "\u10D0\u10DB\u10DD\u10EC\u10DB\u10D4\u10D1\u10E1 \u10EE\u10D4\u10DA\u10DB\u10D8\u10E1\u10D0\u10EC\u10D5\u10D3\u10DD\u10DB \u10DF\u10D4\u10E2\u10DD\u10DC\u10E1 \u10DB\u10D8\u10E1\u10D8 \u10E9\u10D5\u10D4\u10DC\u10D4\u10D1\u10D8\u10E1 \u10D2\u10D0\u10E0\u10D4\u10E8\u10D4.",
    "settings.testConnection": "\u10E2\u10D4\u10E1\u10E2\u10D8 \u10D9\u10D0\u10D5\u10E8\u10D8\u10E0\u10D8",
    "notice.tokenRequired": "\u10E9\u10D0\u10E1\u10D5\u10D8\u10D7 Todoist API \u10DF\u10D4\u10E2\u10DD\u10DC\u10D8 \u10E8\u10D4\u10DC\u10D0\u10EE\u10D5\u10D0\u10DB\u10D3\u10D4.",
