    "error.tokenMissing": "\u0CAF\u0CBE\u0CB5\u0CC1\u0CA6\u0CC7 Todoist API \u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0CB2\u0CAD\u0CCD\u0CAF\u0CB5\u0CBF\u0CB2\u0CCD\u0CB2. Todoist \u0C9F\u0CBE\u0CB8\u0CCD\u0C95\u0CCD \u0CA8\u0CCB\u0C9F\u0CCD\u0CB8\u0CCD \u0CB8\u0CC6\u0C9F\u0CCD\u0C9F\u0CBF\u0C82\u0C97\u0CCD\u200C\u0C97\u0CB3\u0CB2\u0CCD\u0CB2\u0CBF \u0C92\u0C82\u0CA6\u0CA8\u0CCD\u0CA8\u0CC1 \u0C89\u0CB3\u0CBF\u0CB8\u0CBF \u0C85\u0CA5\u0CB5\u0CBE Todoist \u0CB8\u0CBF\u0C82\u0C95\u0CCD \u0C85\u0CA8\u0CCD\u0CA8\u0CC1 \u0C95\u0CBE\u0CA8\u0CCD\u0CAB\u0CBF\u0C97\u0CB0\u0CCD \u0CAE\u0CBE\u0CA1\u0CBF.",
    "error.noTaskPath": "\u0C9F\u0CCA\u0CA1\u0CCA\u0CAF\u0CBF\u0CB8\u0CCD\u0C9F\u0CCD \u0C95\u0CBE\u0CB0\u0CCD\u0CAF {taskId} \u0C97\u0CBE\u0C97\u0CBF \u0CAF\u0CBE\u0CB5\u0CC1\u0CA6\u0CC7 \u0C9F\u0CBF\u0CAA\u0CCD\u0CAA\u0CA3\u0CBF \u0CAE\u0CBE\u0CB0\u0CCD\u0C97\u0CB5\u0CA8\u0CCD\u0CA8\u0CC1 \u0CB0\u0C9A\u0CBF\u0CB8\u0CB2\u0CBE\u0C97\u0CBF\u0CB2\u0CCD\u0CB2",
    "error.pathCollision": "\u0C95\u0CBE\u0CB0\u0CCD\u0CAF \u0C9F\u0CBF\u0CAA\u0CCD\u0CAA\u0CA3\u0CBF \u0CAE\u0CBE\u0CB0\u0CCD\u0C97\u0CB5\u0CC1 \u0C88\u0C97\u0CBE\u0C97\u0CB2\u0CC7 \u0C85\u0CB8\u0CCD\u0CA4\u0CBF\u0CA4\u0CCD\u0CB5\u0CA6\u0CB2\u0CCD\u0CB2\u0CBF\u0CA6\u0CC6: {path}",
    "settings.heading": "\u0CB8\u0CBF\u0C82\u0C95\u0CCD\u0CB0\u0CCA\u0CA8\u0CC8\u0CB8\u0CC7\u0CB6\u0CA8\u0CCD",
    "settings.language": "\u0CAD\u0CBE\u0CB7\u0CC6",
    "settings.languageDescription": "\u0CAA\u0CCD\u0CB2\u0C97\u0CBF\u0CA8\u0CCD \u0CAC\u0CB3\u0CB8\u0CC1\u0CB5 \u0CAD\u0CBE\u0CB7\u0CC6. \u0CB8\u0CBF\u0CB8\u0CCD\u0C9F\u0CAE\u0CCD \u0C85\u0CAC\u0CCD\u0CB8\u0CBF\u0CA1\u0CBF\u0CAF\u0CA8\u0CCD \u0CAE\u0CA4\u0CCD\u0CA4\u0CC1 \u0CA8\u0CBF\u0CAE\u0CCD\u0CAE \u0C86\u0CAA\u0CB0\u0CC7\u0C9F\u0CBF\u0C82\u0C97\u0CCD \u0CB8\u0CBF\u0CB8\u0CCD\u0C9F\u0CAE\u0CCD \u0C85\u0CA8\u0CCD\u0CA8\u0CC1 \u0C85\u0CA8\u0CC1\u0CB8\u0CB0\u0CBF\u0CB8\u0CC1\u0CA4\u0CCD\u0CA4\u0CA6\u0CC6.",
    "settings.rootFolder": "\u0C9F\u0CBE\u0CB8\u0CCD\u0C95\u0CCD-\u0CA8\u0CCB\u0C9F\u0CCD \u0CB0\u0CC2\u0C9F\u0CCD \u0CAB\u0CCB\u0CB2\u0CCD\u0CA1\u0CB0\u0CCD",
    "settings.rootFolderDescription": "\u0CAA\u0CCD\u0CB0\u0CA4\u0CBF \u0C95\u0CBE\u0CB0\u0CCD\u0CAF\u0C95\u0CCD\u0C95\u0CC2 \u0C92\u0C82\u0CA6\u0CC1 \u0CA8\u0CC6\u0CB8\u0CCD\u0C9F\u0CC6\u0CA1\u0CCD \u0CAE\u0CBE\u0CB0\u0CCD\u0C95\u0CCD\u200C\u0CA1\u0CCC\u0CA8\u0CCD \u0C9F\u0CBF\u0CAA\u0CCD\u0CAA\u0CA3\u0CBF\u0CAF\u0CA8\u0CCD\u0CA8\u0CC1 \u0CB0\u0C9A\u0CBF\u0CB8\u0CB2\u0CBE\u0C97\u0CBF\u0CA6\u0CC6.",
    "settings.dashboardNote": "\u0CA1\u0CCD\u0CAF\u0CBE\u0CB6\u0CCD\u200C\u0CAC\u0CCB\u0CB0\u0CCD\u0CA1\u0CCD \u0C9F\u0CBF\u0CAA\u0CCD\u0CAA\u0CA3\u0CBF",
    "settings.interval": "\u0CB8\u0CCD\u0CB5\u0CAF\u0C82\u0C9A\u0CBE\u0CB2\u0CBF\u0CA4 \u0CB8\u0CBF\u0C82\u0C95\u0CCD \u0CAE\u0CA7\u0CCD\u0CAF\u0C82\u0CA4\u0CB0",
    "settings.intervalDescription": "\u0C85\u0CAC\u0CCD\u0CB8\u0CBF\u0CA1\u0CBF\u0CAF\u0CA8\u0CCD \u0CA4\u0CC6\u0CB0\u0CC6\u0CA6\u0CBF\u0CB0\u0CC1\u0CB5\u0CBE\u0C97 \u0CA8\u0CBF\u0CAE\u0CBF\u0CB7\u0C97\u0CB3\u0CC1. \u0CAE\u0CB0\u0CC1\u0CB2\u0CCB\u0CA1\u0CCD \u0CAE\u0CBE\u0CA1\u0CBF\u0CA6 \u0CA8\u0C82\u0CA4\u0CB0 \u0CAA\u0CB0\u0CBF\u0CA3\u0CBE\u0CAE \u0CAC\u0CC0\u0CB0\u0CC1\u0CA4\u0CCD\u0CA4\u0CA6\u0CC6.",
    "settings.token": "Todoist API \u0C9F\u0CCB\u0C95\u0CA8\u0CCD",
    "settings.tokenDescription": "\u0C85\u0CAC\u0CCD\u0CB8\u0CBF\u0CA1\u0CBF\u0CAF\u0CA8\u0CCD \u0CB8\u0CC0\u0C95\u0CCD\u0CB0\u0CC6\u0C9F\u0CCD\u200C\u0CB8\u0CCD\u0C9F\u0CCB\u0CB0\u0CC7\u0C9C\u0CCD\u200C\u0CA8\u0CB2\u0CCD\u0CB2\u0CBF \u0CB8\u0CC1\u0CB0\u0C95\u0CCD\u0CB7\u0CBF\u0CA4\u0CB5\u0CBE\u0C97\u0CBF \u0CB8\u0C82\u0C97\u0CCD\u0CB0\u0CB9\u0CBF\u0CB8\u0CB2\u0CBE\u0C97\u0CBF\u0CA6\u0CC6. \u0C85\u0CA6\u0CA8\u0CCD\u0CA8\u0CC1 \u0C89\u0CB3\u0CBF\u0CB8\u0CB2\u0CC1 \u0C85\u0CA5\u0CB5\u0CBE \u0CAC\u0CA6\u0CB2\u0CBF\u0CB8\u0CB2\u0CC1 \u0CB9\u0CCA\u0CB8 \u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0C85\u0CA8\u0CCD\u0CA8\u0CC1 \u0CA8\u0CAE\u0CC2\u0CA6\u0CBF\u0CB8\u0CBF; \u0C89\u0CB3\u0CBF\u0CB8\u0CBF\u0CA6 \u0CAE\u0CCC\u0CB2\u0CCD\u0CAF\u0CB5\u0CA8\u0CCD\u0CA8\u0CC1 \u0C8E\u0C82\u0CA6\u0CBF\u0C97\u0CC2 \u0CAA\u0CCD\u0CB0\u0CA6\u0CB0\u0CCD\u0CB6\u0CBF\u0CB8\u0CB2\u0CBE\u0C97\u0CC1\u0CB5\u0CC1\u0CA6\u0CBF\u0CB2\u0CCD\u0CB2.",
    "settings.tokenPlaceholderEmpty": "\u0CA8\u0CBF\u0CAE\u0CCD\u0CAE Todoist API \u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0C85\u0CA8\u0CCD\u0CA8\u0CC1 \u0C85\u0C82\u0C9F\u0CBF\u0CB8\u0CBF",
    "settings.tokenPlaceholderSaved": "\u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0C85\u0CA8\u0CCD\u0CA8\u0CC1 \u0CB8\u0CC1\u0CB0\u0C95\u0CCD\u0CB7\u0CBF\u0CA4\u0CB5\u0CBE\u0C97\u0CBF \u0CB8\u0C82\u0C97\u0CCD\u0CB0\u0CB9\u0CBF\u0CB8\u0CB2\u0CBE\u0C97\u0CBF\u0CA6\u0CC6",
    "settings.tokenStatusChecking": "\u0CB8\u0CC1\u0CB0\u0C95\u0CCD\u0CB7\u0CBF\u0CA4 \u0CB8\u0C82\u0C97\u0CCD\u0CB0\u0CB9\u0CA3\u0CC6\u0CAF\u0CA8\u0CCD\u0CA8\u0CC1 \u0CAA\u0CB0\u0CBF\u0CB6\u0CC0\u0CB2\u0CBF\u0CB8\u0CB2\u0CBE\u0C97\u0CC1\u0CA4\u0CCD\u0CA4\u0CBF\u0CA6\u0CC6...",
    "settings.tokenStatusManaged": "\u0C88 \u0CAA\u0CCD\u0CB2\u0C97\u0CBF\u0CA8\u0CCD\u200C\u0C97\u0CBE\u0C97\u0CBF \u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0C85\u0CA8\u0CCD\u0CA8\u0CC1 \u0C89\u0CB3\u0CBF\u0CB8\u0CB2\u0CBE\u0C97\u0CBF\u0CA6\u0CC6.",
    "settings.tokenStatusShared": "\u0C9F\u0CCA\u0CA1\u0CCA\u0CAF\u0CBF\u0CB8\u0CCD\u0C9F\u0CCD \u0CB8\u0CBF\u0C82\u0C95\u0CCD\u200C\u0CA8\u0CBF\u0C82\u0CA6 \u0C88\u0C97\u0CBE\u0C97\u0CB2\u0CC7 \u0CB8\u0C82\u0C97\u0CCD\u0CB0\u0CB9\u0CBF\u0CB8\u0CB2\u0CBE\u0CA6 \u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0C85\u0CA8\u0CCD\u0CA8\u0CC1 \u0CAC\u0CB3\u0CB8\u0CC1\u0CB5\u0CC1\u0CA6\u0CC1.",
    "settings.tokenStatusMissing": "\u0CAA\u0CCD\u0CB0\u0CB8\u0CCD\u0CA4\u0CC1\u0CA4 \u0CAF\u0CBE\u0CB5\u0CC1\u0CA6\u0CC7 \u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0CB2\u0CAD\u0CCD\u0CAF\u0CB5\u0CBF\u0CB2\u0CCD\u0CB2.",
