    "settings.replaceToken": "\u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0CAC\u0CA6\u0CB2\u0CBE\u0CAF\u0CBF\u0CB8\u0CBF",
    "settings.removeToken": "\u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0CA4\u0CC6\u0C97\u0CC6\u0CA6\u0CC1\u0CB9\u0CBE\u0C95\u0CBF",
    "settings.removeTokenTitle": "\u0C89\u0CB3\u0CBF\u0CB8\u0CBF\u0CA6 Todoist \u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0C85\u0CA8\u0CCD\u0CA8\u0CC1 \u0CA4\u0CC6\u0C97\u0CC6\u0CA6\u0CC1\u0CB9\u0CBE\u0C95\u0CC1\u0CB5\u0CC1\u0CA6\u0CC7?",
    "settings.removeTokenDescription": "\u0C87\u0CA6\u0CC1 \u0C9F\u0CCA\u0CA1\u0CCA\u0CAF\u0CBF\u0CB8\u0CCD\u0C9F\u0CCD \u0C95\u0CBE\u0CB0\u0CCD\u0CAF \u0C9F\u0CBF\u0CAA\u0CCD\u0CAA\u0CA3\u0CBF\u0C97\u0CB3\u0CBF\u0C82\u0CA6 \u0C89\u0CB3\u0CBF\u0CB8\u0CB2\u0CBE\u0CA6 \u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0C85\u0CA8\u0CCD\u0CA8\u0CC1 \u0CAE\u0CBE\u0CA4\u0CCD\u0CB0 \u0CA4\u0CC6\u0C97\u0CC6\u0CA6\u0CC1\u0CB9\u0CBE\u0C95\u0CC1\u0CA4\u0CCD\u0CA4\u0CA6\u0CC6. Todoist \u0CB8\u0CBF\u0C82\u0C95\u0CCD\u200C\u0CA8\u0CBF\u0C82\u0CA6 \u0CB8\u0C82\u0C97\u0CCD\u0CB0\u0CB9\u0CBF\u0CB8\u0CB2\u0CBE\u0CA6 \u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0C85\u0CA8\u0CCD\u0CA8\u0CC1 \u0CAC\u0CA6\u0CB2\u0CBE\u0CAF\u0CBF\u0CB8\u0CB2\u0CBE\u0C97\u0CBF\u0CB2\u0CCD\u0CB2.",
    "settings.secretKey": "\u0CB9\u0C82\u0C9A\u0CBF\u0CA6 \u0CB0\u0CB9\u0CB8\u0CCD\u0CAF \u0C95\u0CC0",
    "settings.secretKeyDescription": "\u0C85\u0CB8\u0CCD\u0CA4\u0CBF\u0CA4\u0CCD\u0CB5\u0CA6\u0CB2\u0CCD\u0CB2\u0CBF\u0CB0\u0CC1\u0CB5 \u0CB8\u0CBF\u0C82\u0C95\u0CCD \u0CAA\u0CCD\u0CB2\u0C97\u0CBF\u0CA8\u0CCD\u200C\u0CA8\u0CBF\u0C82\u0CA6 \u0C88\u0C97\u0CBE\u0C97\u0CB2\u0CC7 \u0C95\u0CBE\u0CA8\u0CCD\u0CAB\u0CBF\u0C97\u0CB0\u0CCD \u0CAE\u0CBE\u0CA1\u0CB2\u0CBE\u0CA6 \u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0C85\u0CA8\u0CCD\u0CA8\u0CC1 \u0CAC\u0CB3\u0CB8\u0CC1\u0CA4\u0CCD\u0CA4\u0CA6\u0CC6. \u0C9F\u0CCB\u0C95\u0CA8\u0CCD \u0C85\u0CA8\u0CCD\u0CA8\u0CC1 \u0C87\u0CB2\u0CCD\u0CB2\u0CBF \u0C8E\u0C82\u0CA6\u0CBF\u0C97\u0CC2 \u0C89\u0CB3\u0CBF\u0CB8\u0CB2\u0CBE\u0C97\u0CC1\u0CB5\u0CC1\u0CA6\u0CBF\u0CB2\u0CCD\u0CB2.",
