    "settings.languageDescription": "\u0DB4\u0DCA\u0DBD\u0D9C\u0DD2\u0DB1\u0DBA \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DCF \u0D9A\u0DBB\u0DB1 \u0DB7\u0DCF\u0DC2\u0DCF\u0DC0. \u0DB4\u0DAF\u0DCA\u0DB0\u0DAD\u0DD2\u0DBA Obsidian \u0DC3\u0DC4 \u0D94\u0DB6\u0DDA \u0DB8\u0DD9\u0DC4\u0DD9\u0DBA\u0DD4\u0DB8\u0DCA \u0DB4\u0DAF\u0DCA\u0DB0\u0DAD\u0DD2\u0DBA \u0D85\u0DB1\u0DD4\u0D9C\u0DB8\u0DB1\u0DBA \u0D9A\u0DBB\u0DBA\u0DD2.",
    "settings.rootFolder": "\u0D9A\u0DCF\u0DBB\u0DCA\u0DBA \u0DC3\u0DA7\u0DC4\u0DB1\u0DCA \u0DB8\u0DD6\u0DBD \u0DC6\u0DDD\u0DBD\u0DCA\u0DA9\u0DBB\u0DBA",
    "settings.rootFolderDescription": "\u0DC3\u0DD1\u0DB8 \u0D9A\u0DCF\u0DBB\u0DCA\u0DBA\u0DBA\u0D9A\u0DCA \u0DC3\u0DB3\u0DC4\u0DCF\u0DB8 \u0D91\u0D9A\u0DCA \u0D9A\u0DD0\u0DAF\u0DBD\u0DD2 \u0DC3\u0DBD\u0D9A\u0DD4\u0DAB\u0DD4 \u0DC3\u0DA7\u0DC4\u0DB1\u0D9A\u0DCA \u0DC3\u0DCF\u0DAF\u0DB1\u0DD4 \u0DBD\u0DD0\u0DB6\u0DDA.",
    "settings.dashboardNote": "\u0D8B\u0DB4\u0D9A\u0DBB\u0DAB \u0DB4\u0DD4\u0DC0\u0DBB\u0DD4 \u0DC3\u0DA7\u0DC4\u0DB1",
    "settings.interval": "\u0DC3\u0DCA\u0DC0\u0DBA\u0D82\u0D9A\u0DCA\u200D\u0DBB\u0DD3\u0DBA \u0DC3\u0DB8\u0DB8\u0DD4\u0DC4\u0DD4\u0DBB\u0DCA\u0DAD \u0DB4\u0DBB\u0DAD\u0DBB\u0DBA",
    "settings.intervalDescription": "Obsidian \u0DC0\u0DD2\u0DC0\u0DD8\u0DAD\u0DC0 \u0DAD\u0DD2\u0DB6\u0DD2\u0DBA\u0DAF\u0DD3 \u0DB8\u0DD2\u0DB1\u0DD2\u0DAD\u0DCA\u0DAD\u0DD4. \u0DBB\u0DD3\u0DBD\u0DDD\u0DA9\u0DCA \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8\u0DD9\u0DB1\u0DCA \u0DB4\u0DC3\u0DD4\u0DC0 \u0DB6\u0DBD\u0DCF\u0DAD\u0DCA\u0DB8\u0D9A \u0DC0\u0DDA.",
    "settings.token": "Todoist API \u0DA7\u0DDD\u0D9A\u0DB1\u0DBA",
    "settings.tokenDescription": "Obsidian SecretStorage \u0DC4\u0DD2 \u0D86\u0DBB\u0D9A\u0DCA\u0DC2\u0DD2\u0DAD\u0DC0 \u0D9C\u0DB6\u0DA9\u0DCF \u0D9A\u0DBB \u0D87\u0DAD. \u0D91\u0DBA \u0DC3\u0DD4\u0DBB\u0DD0\u0D9A\u0DD3\u0DB8\u0DA7 \u0DC4\u0DDD \u0DB4\u0DCA\u200D\u0DBB\u0DAD\u0DD2\u0DC3\u0DCA\u0DAE\u0DCF\u0DB4\u0DB1\u0DBA \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8\u0DA7 \u0DB1\u0DC0 \u0DA7\u0DDD\u0D9A\u0DB1\u0DBA\u0D9A\u0DCA \u0D87\u0DAD\u0DD4\u0DC5\u0DAD\u0DCA \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1; \u0DC3\u0DD4\u0DBB\u0D9A\u0DD2\u0DB1 \u0DBD\u0DAF \u0D85\u0D9C\u0DBA \u0D9A\u0DD2\u0DC3\u0DD2 \u0DC0\u0DD2\u0DA7\u0DD9\u0D9A \u0DB1\u0DDC\u0DB4\u0DD9\u0DB1\u0DCA\u0DC0\u0DBA\u0DD2.",
    "settings.tokenPlaceholderEmpty": "\u0D94\u0DB6\u0D9C\u0DDA Todoist API \u0DA7\u0DDD\u0D9A\u0DB1\u0DBA \u0D85\u0DBD\u0DC0\u0DB1\u0DCA\u0DB1",
    "settings.tokenPlaceholderSaved": "\u0DA7\u0DDD\u0D9A\u0DB1\u0DBA\u0D9A\u0DCA \u0D86\u0DBB\u0D9A\u0DCA\u0DC2\u0DD2\u0DAD\u0DC0 \u0D9C\u0DB6\u0DA9\u0DCF \u0D9A\u0DBB \u0D87\u0DAD",
    "settings.tokenStatusChecking": "\u0D86\u0DBB\u0D9A\u0DCA\u0DC2\u0DD2\u0DAD \u0D9C\u0DB6\u0DA9\u0DCF\u0DC0 \u0DB4\u0DBB\u0DD3\u0D9A\u0DCA\u0DC2\u0DCF \u0D9A\u0DBB\u0DB8\u0DD2\u0DB1\u0DCA...",
    "settings.tokenStatusManaged": "\u0DB8\u0DD9\u0DB8 \u0DB4\u0DCA\u0DBD\u0D9C\u0DD2\u0DB1\u0DBA \u0DC3\u0DB3\u0DC4\u0DCF \u0DA7\u0DDD\u0D9A\u0DB1\u0DBA\u0D9A\u0DCA \u0DC3\u0DD4\u0DBB\u0DD0\u0D9A\u0DDA.",
    "settings.tokenStatusShared": "Todoist Sync \u0DC0\u0DD2\u0DC3\u0DD2\u0DB1\u0DCA \u0DAF\u0DD0\u0DB1\u0DA7\u0DB8\u0DAD\u0DCA \u0D9C\u0DB6\u0DA9\u0DCF \u0D9A\u0DBB \u0D87\u0DAD\u0DD2 \u0DA7\u0DDD\u0D9A\u0DB1\u0DBA \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DCF \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8.",
    "settings.tokenStatusMissing": "\u0DAF\u0DD0\u0DB1\u0DA7 \u0D9A\u0DD2\u0DC3\u0DD2\u0DAF\u0DD4 \u0DA7\u0DDD\u0D9A\u0DB1\u0DBA\u0D9A\u0DCA \u0DB1\u0DDC\u0DB8\u0DD0\u0DAD.",
    "settings.saveToken": "\u0DA7\u0DDD\u0D9A\u0DB1\u0DBA \u0DC3\u0DD4\u0DBB\u0D9A\u0DD2\u0DB1\u0DCA\u0DB1",
