    "settings.removeToken": "\u0DA7\u0DDD\u0D9A\u0DB1\u0DBA \u0D89\u0DC0\u0DAD\u0DCA \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
    "settings.removeTokenTitle": "\u0DC3\u0DD4\u0DBB\u0DD0\u0D9A\u0DD2 Todoist \u0DA7\u0DDD\u0D9A\u0DB1\u0DBA \u0D89\u0DC0\u0DAD\u0DCA \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1\u0DAF?",
