    "settings.tokenPlaceholderSaved": "\u0422\u043E\u043A\u0435\u043D \u0458\u0435 \u0431\u0435\u0437\u0431\u0435\u0434\u043D\u043E \u0443\u0441\u043A\u043B\u0430\u0434\u0438\u0448\u0442\u0435\u043D",
    "settings.tokenStatusChecking": "\u041F\u0440\u043E\u0432\u0435\u0440\u0430\u0432\u0430 \u0441\u0435 \u0431\u0435\u0437\u0431\u0435\u0434\u043D\u043E \u0441\u043A\u043B\u0430\u0434\u0438\u0448\u0442\u0435\u2026",
