    "settings.tokenStatusShared": "\u041A\u043E\u0440\u0438\u0448\u045B\u0435\u045A\u0435 \u0442\u043E\u043A\u0435\u043D\u0430 \u043A\u043E\u0458\u0438 \u0458\u0435 \u0432\u0435\u045B \u0443\u0441\u043A\u043B\u0430\u0434\u0438\u0448\u0442\u0438\u043E \u0422\u043E\u0434\u043E\u0438\u0441\u0442 \u0421\u0438\u043D\u0446.",
    "settings.tokenStatusMissing": "\u0422\u0440\u0435\u043D\u0443\u0442\u043D\u043E \u043D\u0438\u0458\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u0430\u043D \u043D\u0438\u0458\u0435\u0434\u0430\u043D \u0442\u043E\u043A\u0435\u043D.",
