    "sync.detachedManual": "\u0412\u0456\u0434'\u0454\u0434\u043D\u0430\u043D\u043E \u0432\u0440\u0443\u0447\u043D\u0443 \u0432 \u043E\u0431\u0441\u0438\u0434\u0456\u0430\u043D\u0456.",
    "sync.remoteDeleted": "\u0412\u0456\u0434\u0434\u0430\u043B\u0435\u043D\u0435 \u0437\u0430\u0432\u0434\u0430\u043D\u043D\u044F \u0432\u0438\u0434\u0430\u043B\u0435\u043D\u043E \u0430\u0431\u043E \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0435.",
    "error.tokenMissing": "\u041C\u0430\u0440\u043A\u0435\u0440 Todoist API \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0438\u0439. \u0417\u0431\u0435\u0440\u0435\u0436\u0456\u0442\u044C \u043E\u0434\u0438\u043D \u0443 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F\u0445 Todoist Task Notes \u0430\u0431\u043E \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0439\u0442\u0435 Todoist Sync.",
