    "settings.heading": "\u0421\u0438\u043D\u0445\u0440\u043E\u043D\u0456\u0437\u0430\u0446\u0456\u044F",
    "settings.language": "\u041C\u043E\u0432\u0430",
    "settings.languageDescription": "\u041C\u043E\u0432\u0430, \u044F\u043A\u0443 \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0454 \u043F\u043B\u0430\u0433\u0456\u043D. \u0421\u0438\u0441\u0442\u0435\u043C\u0430 \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u0430\u0454 Obsidian \u0456 \u0432\u0430\u0448\u0456\u0439 \u043E\u043F\u0435\u0440\u0430\u0446\u0456\u0439\u043D\u0456\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u0456.",
    "settings.rootFolder": "\u041A\u043E\u0440\u0435\u043D\u0435\u0432\u0430 \u043F\u0430\u043F\u043A\u0430 \u0437\u0430\u0434\u0430\u0447\u0456",
    "settings.rootFolderDescription": "\u0414\u043B\u044F \u043A\u043E\u0436\u043D\u043E\u0433\u043E \u0437\u0430\u0432\u0434\u0430\u043D\u043D\u044F \u0441\u0442\u0432\u043E\u0440\u044E\u0454\u0442\u044C\u0441\u044F \u043E\u0434\u043D\u0430 \u0432\u043A\u043B\u0430\u0434\u0435\u043D\u0430 \u043D\u043E\u0442\u0430\u0442\u043A\u0430 Markdown.",
    "settings.dashboardNote": "\u041F\u0440\u0438\u043C\u0456\u0442\u043A\u0430 \u043D\u0430 \u043F\u0430\u043D\u0435\u043B\u0456 \u043F\u0440\u0438\u043B\u0430\u0434\u0456\u0432",
    "settings.interval": "\u0406\u043D\u0442\u0435\u0440\u0432\u0430\u043B \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u043E\u0457 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0456\u0437\u0430\u0446\u0456\u0457",
    "settings.intervalDescription": "\u0425\u0432\u0438\u043B\u0438\u043D, \u043F\u043E\u043A\u0438 Obsidian \u0432\u0456\u0434\u043A\u0440\u0438\u0442\u043E. \u041D\u0430\u0431\u0443\u0432\u0430\u0454 \u0447\u0438\u043D\u043D\u043E\u0441\u0442\u0456 \u043F\u0456\u0441\u043B\u044F \u043F\u0435\u0440\u0435\u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0435\u043D\u043D\u044F.",
    "settings.token": "\u0422\u043E\u043A\u0435\u043D API Todoist",
    "settings.tokenDescription": "\u041D\u0430\u0434\u0456\u0439\u043D\u043E \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u0454\u0442\u044C\u0441\u044F \u0432 Obsidian SecretStorage. \u0412\u0432\u0435\u0434\u0456\u0442\u044C \u043D\u043E\u0432\u0438\u0439 \u043C\u0430\u0440\u043A\u0435\u0440, \u0449\u043E\u0431 \u0437\u0431\u0435\u0440\u0435\u0433\u0442\u0438 \u0430\u0431\u043E \u0437\u0430\u043C\u0456\u043D\u0438\u0442\u0438 \u0439\u043E\u0433\u043E; \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043D\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u043D\u0456\u043A\u043E\u043B\u0438 \u043D\u0435 \u0432\u0456\u0434\u043E\u0431\u0440\u0430\u0436\u0430\u0454\u0442\u044C\u0441\u044F.",
    "settings.tokenPlaceholderEmpty": "\u0412\u0441\u0442\u0430\u0432\u0442\u0435 \u043C\u0430\u0440\u043A\u0435\u0440 Todoist API",
    "settings.tokenPlaceholderSaved": "\u0422\u043E\u043A\u0435\u043D \u043D\u0430\u0434\u0456\u0439\u043D\u043E \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u0454\u0442\u044C\u0441\u044F",
